      "note": "حدود النقل: متن الرواية المختارة كاملًا دون الإسناد، مع سياق الحوار وقيود الرواة.\nملاحظة المراجعة: أُثبت الحديث كله، من تنفيس الكربة إلى «لم يسرع به نسبه»، بما فيه العلم واجتماع تلاوة القرآن.",
