    "title": "مواساة عند الشدة",
    "body": "قال النبي ﷺ:\n«ما يصيب المسلم من نصب ولا وصب ولا هم ولا حزن ولا أذى ولا غم حتى الشوكة يشاكها، إلا كفر الله بها من خطاياه».",
