    "body": "عن عائشة رضي الله عنها، قالت:\nفقدت رسول الله ﷺ ليلة من الفراش فالتمسته، فوقعت يدي على بطن قدميه وهو في المسجد وهما منصوبتان، وهو يقول: «اللهم أعوذ برضاك من سخطك وبمعافاتك من عقوبتك، وأعوذ بك منك، لا أحصي ثناء عليك، أنت كما أثنيت على نفسك».",
