    "title": "إصلاح ذات البين",
    "body": "قال رسول الله ﷺ:\n«تفتح أبواب الجنة يوم الاثنين ويوم الخميس، فيغفر لكل عبد لا يشرك بالله شيئًا إلا رجلًا كانت بينه وبين أخيه شحناء، فيقال: أَنْظِروا هذين حتى يصطلحا، أَنْظِروا هذين حتى يصطلحا، أَنْظِروا هذين حتى يصطلحا».",
    "narratorLine": "أبو هريرة رضي الله عنه.",
