    "body": "قال النبي ﷺ:\n«الخازن المسلم الأمين الذي يُنْفِذُ ما أمر به كاملًا موفرًا، طيّبٌ به نفسه، فيدفعه إلى الذي أمر له به، أحد المتصدقين».\nوفي الرواية: وربما قال: يعطي.",
