    "body": "قال سعد بن أبي وقاص رضي الله عنه: كنا عند رسول الله ﷺ فقال: «أيعجز أحدكم أن يكسب كل يوم ألف حسنة؟». فسأله سائل من جلسائه: كيف يكسب أحدنا ألف حسنة؟ قال: «يسبح مائة تسبيحة، فيكتب له ألف حسنة أو يحط عنه ألف خطيئة».",
    "narratorLine": "سعد بن أبي وقاص رضي الله عنه.",
