    "title": "التعوذ بكلمات الله",
    "body": "قال ابن عباس رضي الله عنهما: كان النبي ﷺ يعوِّذ الحسن والحسين ويقول:\n«إن أباكما كان يعوِّذ بها إسماعيل وإسحاق، أعوذ بكلمات الله التامة من كل شيطان وهامة، ومن كل عين لامَّة».",
