    "body": "عن عائشة رضي الله عنها، أن النبي ﷺ كان يعوِّذ بعض أهله، يمسح بيده اليمنى ويقول:\n«اللهم رب الناس أذهب الباس، اشفه وأنت الشافي، لا شفاء إلا شفاؤك، شفاءً لا يغادر سقمًا».",
