    "body": "عن أبي هريرة رضي الله عنه، أن رجلًا قال: يا رسول الله، إن لي قرابة أصلهم ويقطعوني وأحسن إليهم ويسيئون إليَّ وأحلم عنهم ويجهلون عليَّ. فقال:\n«لئن كنت كما قلت فكأنما تُسِفُّهم المَلَّ، ولا يزال معك من الله ظهير عليهم ما دمت على ذلك».",
