      "note": "حدود النقل: المتن النبوي كاملًا دون الإسناد.\nملاحظة المراجعة: أُبقي «وأموالكم» و«وأعمالكم»؛ لم نقتصر على جملة القلوب أو نستبدل لفظ الصور بلفظ رواية أخرى.",
