    "editorialNumber": 124,
    "title": "الشفاعة في الحاجة",
    "body": "قال أبو موسى رضي الله عنه: كان رسول الله ﷺ إذا أتاه طالب حاجة أقبل على جلسائه فقال:\n«اشفعوا فلتؤجروا، وليقض الله على لسان نبيه ما أحب».",
    "narratorLine": "أبو موسى الأشعري رضي الله عنه.",
