      "reference": "رواه مسلم.",
      "note": "حدود النقل: المتن المختار كاملًا بفقرتي المحبة والبغض، دون الإسناد.\nملاحظة المراجعة: أُبقيت فقرة البغض كاملة ومواضع وصل النقل بلفظ «قال» الأربعة كما في النص العربي؛ لم تُضم رواية أخرى إلى هذه الرواية.",
