      "note": "حدود النقل: المتن النبوي كاملًا دون الإسناد.\nملاحظة المراجعة: نُقل لفظ البخاري ٥٩٨٤ كاملًا؛ لم تُضف كلمة «رحم» داخل الاقتباس. يرد المصدر في أبواب صلة الرحم من كتاب الأدب.",
