    "body": "قال النبي ﷺ:\n«لأن يأخذ أحدكم حبله فيأتي بحزمة الحطب على ظهره فيبيعها، فيكف الله بها وجهه، خير له من أن يسأل الناس أعطوه أو منعوه».",
