    "body": "قال أبو هريرة رضي الله عنه: كان رسول الله ﷺ يقول:\n«اللهم أصلح لي ديني الذي هو عصمة أمري، وأصلح لي دنياي التي فيها معاشي، وأصلح لي آخرتي التي فيها معادي، واجعل الحياة زيادة لي في كل خير، واجعل الموت راحة لي من كل شر».",
