    "body": "عن أنس رضي الله عنه، أن رسول الله ﷺ كان إذا أوى إلى فراشه قال:\n«الحمد لله الذي أطعمنا وسقانا وكفانا وآوانا، فكم ممن لا كافي له ولا مؤوي».",
