    "body": "قال أبو ذر رضي الله عنه: قلت: يا رسول الله، ألا تستعملني؟ قال: فضرب بيده على منكبي، ثم قال:\n«يا أبا ذر، إنك ضعيف وإنها أمانة، وإنها يوم القيامة خزي وندامة إلا من أخذها بحقها وأدى الذي عليه فيها».",
