    "title": "كتابة الحسنات والسيئات",
    "body": "عن ابن عباس رضي الله عنهما، عن النبي ﷺ فيما يروي عن ربه عز وجل قال:\n«إن الله كتب الحسنات والسيئات، ثم بين ذلك، فمن هم بحسنة فلم يعملها كتبها الله له عنده حسنة كاملة، فإن هو هم بها فعملها كتبها الله له عنده عشر حسنات إلى سبعمائة ضعف إلى أضعاف كثيرة، ومن هم بسيئة فلم يعملها كتبها الله له عنده حسنة كاملة، فإن هو هم بها فعملها كتبها الله له سيئة واحدة».",
