    "editorialNumber": 155,
    "title": "الحلال والحرام وصلاح القلب",
    "body": "قال النعمان بن بشير رضي الله عنهما: سمعت رسول الله ﷺ يقول:\n«الحلال بيّن والحرام بيّن، وبينهما مُشبَّهات لا يعلمها كثير من الناس، فمن اتقى المُشبَّهات استبرأ لدينه وعرضه، ومن وقع في الشبهات كراع يرعى حول الحمى يوشك أن يواقعه. ألا وإن لكل ملك حمى، ألا إن حمى الله في أرضه محارمه، ألا وإن في الجسد مضغة إذا صلحت صلح الجسد كله وإذا فسدت فسد الجسد كله، ألا وهي القلب».",
