    "title": "حق صاحب اليمين",
    "body": "عن سهل بن سعد رضي الله عنه، أن رسول الله ﷺ أُتي بشراب فشرب منه، وعن يمينه غلام وعن يساره الأشياخ، فقال للغلام: «أتأذن لي أن أعطي هؤلاء؟». فقال الغلام: والله يا رسول الله، لا أوثر بنصيبي منك أحدًا. قال: فتله رسول الله ﷺ في يده.",
