    "body": "قال سهل بن سعد رضي الله عنه: اطلع رجل من جحر في حجر النبي ﷺ، ومع النبي ﷺ مدرى يحك به رأسه، فقال:\n«لو أعلم أنك تنظر لطعنت به في عينك، إنما جعل الاستئذان من أجل البصر».",
