    "editorialNumber": 174,
    "title": "حق الطريق",
    "body": "قال النبي ﷺ: «إياكم والجلوس على الطرقات». فقالوا: ما لنا بد، إنما هي مجالسنا نتحدث فيها. قال: «فإذا أبيتم إلا المجالس فأعطوا الطريق حقها». قالوا: وما حق الطريق؟ قال: «غض البصر، وكف الأذى، ورد السلام، وأمر بالمعروف، ونهي عن المنكر».",
