    "body": "قال ربيعة بن كعب الأسلمي رضي الله عنه: كنت أبيت مع رسول الله ﷺ فأتيته بوضوئه وحاجته، فقال لي: «سل». فقلت: أسألك مرافقتك في الجنة. قال: «أوغير ذلك؟». قلت: هو ذاك. قال: «فأعني على نفسك بكثرة السجود».",
