    "title": "تعلم الصلاة وتعليمها",
    "body": "قال مالك بن الحويرث رضي الله عنه: أتينا إلى النبي ﷺ ونحن شببة متقاربون، فأقمنا عنده عشرين يومًا وليلة، وكان رسول الله ﷺ رحيمًا رفيقًا، فلما ظن أنا قد اشتهينا أهلنا أو قد اشتقنا سألنا عمن تركنا بعدنا فأخبرناه، قال:\n«ارجعوا إلى أهليكم فأقيموا فيهم وعلموهم ومروهم».\nوذكر أشياء أحفظها أو لا أحفظها.\n«وصلوا كما رأيتموني أصلي، فإذا حضرت الصلاة فليؤذن لكم أحدكم وليؤمكم أكبركم».",
