    "body": "عن عائشة رضي الله عنها، أن نبي الله ﷺ كان يقوم من الليل حتى تتفطر قدماه، فقالت عائشة: لم تصنع هذا يا رسول الله وقد غفر الله لك ما تقدم من ذنبك وما تأخر؟ قال: «أفلا أحب أن أكون عبدًا شكورًا؟». فلما كثر لحمه صلى جالسًا، فإذا أراد أن يركع قام فقرأ ثم ركع.",
