    "title": "الفاتحة وخواتيم البقرة",
    "body": "قال ابن عباس رضي الله عنهما: بينما جبريل قاعد عند النبي ﷺ سمع نقيضًا من فوقه فرفع رأسه فقال: هذا باب من السماء فتح اليوم لم يفتح قط إلا اليوم. فنزل منه ملك فقال: هذا ملك نزل إلى الأرض لم ينزل قط إلا اليوم. فسلم وقال: أبشر بنورين أوتيتهما لم يؤتهما نبي قبلك: فاتحة الكتاب وخواتيم سورة البقرة، لن تقرأ بحرف منهما إلا أعطيته.",
