      "note": "حدود النقل: المتن كاملًا بذكري النوم والاستيقاظ، دون الإسناد.\nملاحظة المراجعة: اختير لفظ البخاري ٦٣١٢ دون إضافة «اللهم» من طريق آخر؛ أُبقي ذكر الاستيقاظ.",
