    "body": "قال إبراهيم السكسكي: سمعت أبا بردة، واصطحب هو ويزيد بن أبي كبشة في سفر، فكان يزيد يصوم في السفر، فقال له أبو بردة: سمعت أبا موسى مرارًا يقول: قال رسول الله ﷺ:\n«إذا مرض العبد أو سافر، كتب له مثل ما كان يعمل مقيمًا صحيحًا».",
