    "body": "قال النبي ﷺ:\n«مثل الذي يقرأ القرآن كالأترجة طعمها طيب وريحها طيب، والذي لا يقرأ القرآن كالتمرة طعمها طيب ولا ريح لها، ومثل الفاجر الذي يقرأ القرآن كمثل الريحانة ريحها طيب وطعمها مر، ومثل الفاجر الذي لا يقرأ القرآن كمثل الحنظلة طعمها مر ولا ريح لها».",
