    "body": "قال النبي ﷺ:\n«من قام ليلة القدر إيمانًا واحتسابًا غفر له ما تقدم من ذنبه، ومن صام رمضان إيمانًا واحتسابًا غفر له ما تقدم من ذنبه».",
