    "body": "قال جابر بن عبد الله رضي الله عنهما: كان رسول الله ﷺ في سفر، فرأى زحامًا ورجلًا قد ظُلِّل عليه، فقال: «ما هذا؟». فقالوا: صائم. فقال:\n«ليس من البر الصوم في السفر».",
