    "title": "المبادرة بالصدقة",
    "body": "قال أبو هريرة رضي الله عنه: جاء رجل إلى النبي ﷺ فقال: يا رسول الله، أي الصدقة أعظم أجرًا؟ قال:\n«أن تصدق وأنت صحيح شحيح، تخشى الفقر وتأمل الغنى، ولا تمهل حتى إذا بلغت الحلقوم قلت: لفلان كذا، ولفلان كذا، وقد كان لفلان».",
    "narratorLine": "أبو هريرة رضي الله عنه.",
