    "title": "لا تعيير ولا تكليف فوق الطاقة",
    "body": "قال المعرور: لقيت أبا ذر بالربذة، وعليه حلة وعلى غلامه حلة، فسألته عن ذلك، فقال: إني ساببت رجلًا فعيرته بأمه، فقال لي النبي ﷺ:\n«يا أبا ذر، أعيرته بأمه؟ إنك امرؤ فيك جاهلية، إخوانكم خولكم، جعلهم الله تحت أيديكم، فمن كان أخوه تحت يده فليطعمه مما يأكل وليلبسه مما يلبس، ولا تكلفوهم ما يغلبهم، فإن كلفتموهم فأعينوهم».",
