    "body": "عن عمر بن الخطاب رضي الله عنه: قدم على النبي ﷺ سبي، فإذا امرأة من السبي قد تحلب ثديها تسقي، إذا وجدت صبيًا في السبي أخذته فألصقته ببطنها وأرضعته، فقال لنا النبي ﷺ: «أترون هذه طارحة ولدها في النار؟». قلنا: لا، وهي تقدر على أن لا تطرحه. فقال:\n«الله أرحم بعباده من هذه بولدها».",
