    "body": "قال أبو وائل: عدنا خبابًا فقال: هاجرنا مع النبي ﷺ نريد وجه الله، فوقع أجرنا على الله، فمنا من مضى لم يأخذ من أجره، منهم مصعب بن عمير، قتل يوم أحد وترك نَمِرَة، فإذا غطينا رأسه بدت رجلاه، وإذا غطينا رجليه بدا رأسه، فأمرنا النبي ﷺ أن نغطي رأسه ونجعل على رجليه من الإذخر، ومنا من أينعت له ثمرته فهو يَهْدُبُها.",
