    "title": "النداء والصف الأول",
    "body": "قال رسول الله ﷺ:\n«لو يعلم الناس ما في النداء والصف الأول، ثم لم يجدوا إلا أن يستهموا عليه لاستهموا، ولو يعلمون ما في التهجير لاستبقوا إليه، ولو يعلمون ما في العتمة والصبح لأتوهما ولو حبوًا».",
    "narratorLine": "أبو هريرة رضي الله عنه.",
