      "body": "عن أنس بن مالك رضي الله عنه قال:\nمر النبي ﷺ بامرأة تبكي عند قبر فقال: «اتقي الله واصبري». قالت: إليك عني، فإنك لم تصب بمصيبتي، ولم تعرفه. فقيل لها إنه النبي ﷺ. فأتت باب النبي ﷺ فلم تجد عنده بوابين فقالت: لم أعرفك. فقال: «إنما الصبر عند الصدمة الأولى».",
      "narratorLine": "أنس بن مالك رضي الله عنه.",
