      "editorialNumber": 264,
      "title": "الدعاء عند المصيبة",
      "body": "عن أم سلمة رضي الله عنها أنها قالت:\nسمعت رسول الله ﷺ يقول: «ما من مسلم تصيبه مصيبة فيقول ما أمره الله إنا لله وإنا إليه راجعون اللهم أْجُرني في مصيبتي وأخلف لي خيرا منها؛ إلا أخلف الله له خيرا منها». قالت: فلما مات أبو سلمة قلت: أي المسلمين خير من أبي سلمة أول بيت هاجر إلى رسول الله ﷺ. ثم إني قلتها فأخلف الله لي رسول الله ﷺ. قالت: أرسل إليّ رسول الله ﷺ حاطب بن أبي بلتعة يخطبني له فقلت: إن لي بنتا وأنا غيور. فقال: «أما ابنتها فندعو الله أن يغنيها عنها وأدعو الله أن يذهب بالغيرة».",
      "narratorLine": "أم سلمة رضي الله عنها.",
