      "editorialNumber": 268,
      "title": "في خدمة أهله",
      "body": "عن الأسود قال:\nسألت عائشة: ما كان النبي ﷺ يصنع في بيته؟ قالت: كان يكون في مِهنة أهله — تعني خدمة أهله — فإذا حضرت الصلاة خرج إلى الصلاة.",
