      "title": "باب التوبة",
      "body": "قال نبي الله ﷺ:\n«كان فيمن كان قبلكم رجل قتل تسعة وتسعين نفسا فسأل عن أعلم أهل الأرض فدل على راهب فأتاه فقال: إنه قتل تسعة وتسعين نفسا فهل له من توبة؟ فقال: لا. فقتله فكمل به مائة ثم سأل عن أعلم أهل الأرض فدل على رجل عالم فقال: إنه قتل مائة نفس فهل له من توبة؟ فقال: نعم ومن يحول بينه وبين التوبة؟ انطلق إلى أرض كذا وكذا فإن بها أناسا يعبدون الله فاعبد الله معهم ولا ترجع إلى أرضك فإنها أرض سوء. فانطلق حتى إذا نصف الطريق أتاه الموت فاختصمت فيه ملائكة الرحمة وملائكة العذاب فقالت ملائكة الرحمة: جاء تائبا مقبلا بقلبه إلى الله. وقالت ملائكة العذاب: إنه لم يعمل خيرا قط. فأتاهم ملك في صورة آدمي فجعلوه بينهم فقال: قيسوا ما بين الأرضين فإلى أيتهما كان أدنى فهو له. فقاسوه فوجدوه أدنى إلى الأرض التي أراد فقبضته ملائكة الرحمة». قال قتادة: فقال الحسن: ذكر لنا أنه لما أتاه الموت نأى بصدره.",
