      "title": "أبواب الصدقة",
      "body": "عن أبي ذر رضي الله عنه:\nأن ناسا من أصحاب النبي ﷺ قالوا للنبي ﷺ: يا رسول الله ذهب أهل الدثور بالأجور يصلون كما نصلي ويصومون كما نصوم ويتصدقون بفضول أموالهم. قال: «أوليس قد جعل الله لكم ما تَصَدَّقون؟ إن بكل تسبيحة صدقة وكل تكبيرة صدقة وكل تحميدة صدقة وكل تهليلة صدقة وأمر بالمعروف صدقة ونهي عن منكر صدقة وفي بُضع أحدكم صدقة». قالوا: يا رسول الله، أيأتي أحدنا شهوته ويكون له فيها أجر؟ قال: «أرأيتم لو وضعها في حرام أكان عليه فيها وزر؟ فكذلك إذا وضعها في الحلال كان له أجر».",
      "narratorLine": "أبو ذر الغفاري رضي الله عنه.",
