      "title": "مثل البخيل والمنفق",
      "body": "قال رسول الله ﷺ:\n«مثل البخيل والمنفق كمثل رجلين، عليهما جُبَّتان من حديد، من ثديهما إلى تراقيهما، فأما المنفق فلا ينفق إلا سبغت» — أو وفرت — «على جلده حتى تخفي بنانه وتعفو أثره، وأما البخيل فلا يريد أن ينفق شيئا إلا لزقت كل حلقة مكانها، فهو يوسعها ولا تتسع».",
