      "body": "قال النبي ﷺ:\n«مثل ما بعثني الله به من الهدى والعلم كمثل الغيث الكثير أصاب أرضا، فكان منها نقية قبلت الماء، فأنبتت الكلأ والعشب الكثير، وكانت منها أجادب أمسكت الماء، فنفع الله بها الناس، فشربوا وسقوا وزرعوا، وأصابت منها طائفة أخرى، إنما هي قيعان لا تمسك ماء، ولا تنبت كلأ، فذلك مثل من فَقُهَ في دين الله ونفعه ما بعثني الله به، فعَلِمَ وعلَّمَ، ومثل من لم يرفع بذلك رأسا، ولم يقبل هدى الله الذي أرسلت به».",
