      "title": "دعاء الاستخارة",
      "body": "عن جابر بن عبد الله رضي الله عنهما قال:\nكان رسول الله ﷺ يعلمنا الاستخارة في الأمور كما يعلمنا السورة من القرآن يقول: «إذا هم أحدكم بالأمر فليركع ركعتين من غير الفريضة ثم ليقل: اللهم إني أستخيرك بعلمك وأستقدرك بقدرتك، وأسألك من فضلك العظيم، فإنك تقدر ولا أقدر وتعلم ولا أعلم وأنت علام الغيوب، اللهم إن كنت تعلم أن هذا الأمر خير لي في ديني ومعاشي وعاقبة أمري» — أو قال عاجل أمري وآجله — «فاقدره لي ويسره لي ثم بارك لي فيه، وإن كنت تعلم أن هذا الأمر شر لي في ديني ومعاشي وعاقبة أمري» — أو قال في عاجل أمري وآجله — «فاصرفه عني واصرفني عنه، واقدر لي الخير حيث كان ثم أرضني به» — قال — ويسمي حاجته.",
