      "body": "قال النبي ﷺ:\n«إن الله خلق الخلق حتى إذا فرغ من خلقه، قالت الرحم: هذا مقام العائذ بك من القطيعة. قال: نعم، أما ترضين أن أصل من وصلك وأقطع من قطعك؟ قالت: بلى يا رب. قال: فهو لك». قال رسول الله ﷺ: «فاقرءوا إن شئتم ﴿فهل عسيتم إن توليتم أن تفسدوا في الأرض وتقطعوا أرحامكم﴾».",
