      "title": "العناية بالبيت ليلًا",
      "body": "قال رسول الله ﷺ:\n«غطوا الإناء وأوكوا السقاء وأغلقوا الباب وأطفئوا السراج؛ فإن الشيطان لا يحل سقاء ولا يفتح بابا ولا يكشف إناء، فإن لم يجد أحدكم إلا أن يعرض على إنائه عودا ويذكر اسم الله فليفعل؛ فإن الفويسقة تضرم على أهل البيت بيتهم».",
      "narratorLine": "جابر بن عبد الله رضي الله عنهما.",
