      "id": "post-hundred-dhikr-and-its-conditions",
      "editorialNumber": 348,
      "title": "التهليل والتسبيح مائة مرة",
      "body": "قال رسول الله ﷺ:\n«من قال: لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير، في يوم مائة مرة، كانت له عَدْل عشر رقاب وكتبت له مائة حسنة ومحيت عنه مائة سيئة وكانت له حرزا من الشيطان يومه ذلك حتى يمسي ولم يأت أحد أفضل مما جاء به إلا أحد عمل أكثر من ذلك. ومن قال: سبحان الله وبحمده في يوم مائة مرة حطت خطاياه ولو كانت مثل زبد البحر».",
