      "body": "عن عبد الله بن مسعود رضي الله عنه قال:\nقال لي النبي ﷺ: «اقرأ عليّ». قلت: يا رسول الله، آقرأ عليك وعليك أنزل؟ قال: «نعم». فقرأت سورة النساء حتى أتيت إلى هذه الآية ﴿فكيف إذا جئنا من كل أمة بشهيد وجئنا بك على هؤلاء شهيدا﴾ قال: «حسبك الآن». فالتفت إليه فإذا عيناه تذرفان.",
