      "editorialNumber": 353,
      "title": "يرفع الله بهذا الكتاب",
      "body": "عن عامر بن واثلة:\nأن نافع بن عبد الحارث لقي عمر بعسفان وكان عمر يستعمله على مكة فقال: من استعملت على أهل الوادي؟ فقال: ابن أبزى. قال: ومن ابن أبزى؟ قال: مولى من موالينا. قال: فاستخلفت عليهم مولى؟ قال: إنه قارئ لكتاب الله عز وجل وإنه عالم بالفرائض. قال عمر: أما إن نبيكم ﷺ قد قال: «إن الله يرفع بهذا الكتاب أقواما ويضع به آخرين».",
      "narratorLine": "عمر بن الخطاب رضي الله عنه؛ في خبر نافع بن عبد الحارث الذي رواه عامر بن واثلة.",
