      "body": "عن جرير بن عبد الله رضي الله عنه قال:\nكنا عند رسول الله ﷺ في صدر النهار، قال: فجاءه قوم حفاة عراة مجتابي النمار أو العباء متقلدي السيوف عامتهم من مضر بل كلهم من مضر فتمعر وجه رسول الله ﷺ لما رأى بهم من الفاقة فدخل ثم خرج فأمر بلالا فأذن وأقام فصلى ثم خطب فقال: «﴿يا أيها الناس اتقوا ربكم الذي خلقكم من نفس واحدة﴾» إلى آخر الآية «﴿إن الله كان عليكم رقيبا﴾» والآية التي في الحشر «﴿اتقوا الله ولتنظر نفس ما قدمت لغد واتقوا الله﴾ تصدق رجل من ديناره من درهمه من ثوبه من صاع بُرِّه من صاع تمره» — حتى قال — «ولو بشق تمرة». قال: فجاء رجل من الأنصار بصرة كادت كفه تعجز عنها بل قد عجزت — قال — ثم تتابع الناس حتى رأيت كومين من طعام وثياب حتى رأيت وجه رسول الله ﷺ يتهلل كأنه مُذْهَبة فقال رسول الله ﷺ: «من سن في الإسلام سنة حسنة فله أجرها وأجر من عمل بها بعده من غير أن ينقص من أجورهم شيء ومن سن في الإسلام سنة سيئة كان عليه وزرها ووزر من عمل بها من بعده من غير أن ينقص من أوزارهم شيء».",
